pub fn point_claims(
    columns: &[Vec<QM31>; 29],
    point: &[QM31; 10],
) -> Result<[[QM31; 29]; 3], Error> {
    let mut claims = [[QM31::ZERO; 29]; 3];
    for (p, at) in wire::statement_points(point).iter().enumerate() {
        for (lane, column) in columns.iter().enumerate() {
            claims[p][lane] = multilinear_evaluate_qm31(column, at).ok_or(Error::Public)?;
        }
    }
    Ok(claims)
}

    commitments: &mut impl Commitments,
    hash: HashFn,
    transported_endpoints: bool,
) -> Result<BuiltSemantics, Error> {
    // Reject raw noncanonical constructors rather than normalize their
    // commitment representation. D is supplied before any challenge.
    if c1
        .iter()
        .any(|v| v.len() != 1024 || v.iter().any(|x| x.0 >= P))
        || d.iter().chain(g).any(|x| {
            QM31::from_le_bytes(&{
                let mut b = [0; 16];
                x.write_le_bytes(&mut b);
                b
            })
            .is_none()
        })
    {
        return Err(Error::Public);
    }
    let base: [&[M31; 1024]; 26] =
        core::array::from_fn(|i| c1[i].as_slice().try_into().unwrap());
    let first = core::array::from_fn(|i| {
        if i < 26 {
            Column::Base(base[i])
        } else {
            Column::Extension(d)
        }
    });
    let c1_root = commitments.c1(first)?;
    let mut transcript = SemanticTranscript::new(hash, &public.public_bytes()?, &c1_root)?;
    let mut bytes = c1_root.to_vec();
    let mut scalar = |row, payload: &[u8], transcript: &mut SemanticTranscript| {
        let framed = wire::record(row, payload)?;
        let value = transcript.semantic(row, &framed)?;
        bytes.extend_from_slice(&framed);
        Ok::<QM31, Error>(value)
    };
    let lambda = scalar(0, &[], &mut transcript)?;
    let chi = scalar(1, &[], &mut transcript)?;
    let h1 = helper(lambda, chi)?;
    let h1: &[QM31; 1024] = h1.as_slice().try_into().map_err(|_| Error::Public)?;
    if state_only_copy_helper_sum(h1) != Some(QM31::ZERO) {
        return Err(Error::Public);
    }
    let c2_root = commitments.c2([h1, g])?;
    let theta = scalar(2, &c2_root, &mut transcript)?;
    let mut zc = [QM31::ZERO; 10];
    for (i, value) in zc.iter_mut().enumerate() {
        *value = scalar(3 + i as u8, &[], &mut transcript)?;
    }
    let mu = scalar(13, &[], &mut transcript)?;
    let columns: [Vec<QM31>; 29] = core::array::from_fn(|lane| match lane {
        0..=25 => c1[lane].iter().copied().map(lift).collect(),
        26 => h1.to_vec(),
        27 => g.to_vec(),
        _ => d.to_vec(),
    });
    let mut mask_sum = QM31::ZERO;
    for row in 0..1024 {
        let point = core::array::from_fn(|i| {
            if (row >> (9 - i)) & 1 == 0 {
                QM31::ZERO
            } else {
                QM31::ONE
            }
        });
        mask_sum = mask_sum.add(
            aspis_core::state_only_hiding::state_only_selected_mask_value(
                &core::array::from_fn(|i| columns[i][row]),
                &core::array::from_fn(|i| columns[16 + i][row]),
                columns[27][row],
                &point,
            ),
        );
    }
    let eta = scalar(
        14,
        &WideExact::from_qm31(mask_sum).to_le_bytes(),
        &mut transcript,
    )?;
    let challenges = Challenges {
        lambda,
        chi,
        theta,
        zc,
        mu,
        eta,
    };
    let (alpha, _) = crate::state_only_hiding::r0::prove_sumcheck(
        &mut transcript,
        &mut bytes,
        mask_sum,
        |point| {
            let claims = point_claims(&columns, point)?;
            let terminal = public.terminal_qm31(&claims, point, &challenges)?;
            let mask = aspis_core::state_only_hiding::state_only_selected_mask_value(
                &core::array::from_fn(|i| claims[0][i]),
                &core::array::from_fn(|i| claims[0][16 + i]),
                claims[0][27],
                point,
            );
            Ok(mask.add(eta.mul(terminal)))
        },
    )?;
    let claims = point_claims(&columns, &alpha)?;
    let state_before_z0 = transcript.state();
    let before_z0 = wire::record(
        25,
        &wire::encode_values(claims.into_iter().flatten().map(WideExact::from_qm31)),
    )?;

pub fn prove_sumcheck(
    transcript: &mut SemanticTranscript,
    output: &mut Vec<u8>,
    initial_claim: QM31,
    mut oracle: impl FnMut(&[QM31; 10]) -> Result<QM31, Error>,
) -> Result<([QM31; 10], QM31), Error> {
    let mut point = [QM31::ZERO; 10];
    let mut running = initial_claim;
    for round in 0..10 {
        let remaining = 9 - round;
        let mut values = [QM31::ZERO; 28];
        for (sample, value) in values.iter_mut().enumerate() {
            point[round] = QM31::from_cm31(CM31::from_m31(M31(sample as u32)));
            for assignment in 0..1usize << remaining {
                for offset in 0..remaining {
                    point[round + 1 + offset] =
                        if (assignment >> (remaining - 1 - offset)) & 1 == 0 {
                            QM31::ZERO
                        } else {
                            QM31::ONE
                        };
                }
                *value = value.add(oracle(&point)?);
            }
        }
        let polynomial = interpolate(&values);
        if state_only_boundary_sum(&polynomial) != running {
            return Err(Error::Boundary { round });
        }
        let framed = wire::record(
            15 + round as u8,
            &wire::encode_values(polynomial.map(WideExact::from_qm31)),
        )?;
        point[round] = transcript.semantic(15 + round as u8, &framed)?;
        output.extend_from_slice(&framed);
        running = evaluate_state_only_polynomial(&polynomial, point[round]);
    }
    if oracle(&point)? != running {
        return Err(Error::Terminal);
    }
    Ok((point, running))
}

pub fn new(hash: HashFn, public_bytes: &[u8], c1_root: &[u8; 32]) -> Result<Self, Error> {
    let length = u32::try_from(public_bytes.len()).map_err(|_| Error::Public)?;
    Ok(Self {
        state: hash(&[DOMAIN, &[0], &length.to_le_bytes(), public_bytes, c1_root]),
        hash,
        next_row: 0,
    })
}
pub fn state(&self) -> [u8; 32] {
    self.state
}
pub fn next_row(&self) -> u8 {
    self.next_row
}

fn sample_block(&mut self, row: u8, framed: &[u8]) -> Result<[u8; 32], Error> {
    if row != self.next_row {
        return Err(Error::RowOrder {
            expected: self.next_row,
            actual: row,
        });
    }
    parse_record(row, framed)?;
    // Exactly one absorb, one squeeze and one advance. Both reads
    // use s_abs; advancing from the challenge block would be wrong.
    let absorbed = (self.hash)(&[&self.state, &[0, 0xa0 + row], framed]);
    let block = (self.hash)(&[&absorbed, &[1]]);
    self.state = (self.hash)(&[&absorbed, &[2]]);
    self.next_row += 1;
    Ok(block)
}
pub fn semantic(&mut self, row: u8, framed: &[u8]) -> Result<QM31, Error> {
    if row > 24 {
        return Err(Error::InvalidRow);
    }
    Ok(qm31_sample(&self.sample_block(row, framed)?))
}
/// R-B's one-block reference-circle map, including fixed fallback.

fn state_only_statement_points(z: &[QM31; 10]) -> [[QM31; 10]; 3] {
    let mut successor = *z;
    let mut carry = QM31::ONE;
    for coordinate in (0..z.len()).rev() {
        let bit = z[coordinate];
        let bit_and_carry = bit.mul(carry);
        successor[coordinate] = bit.add(carry).sub(bit_and_carry.add(bit_and_carry));
        carry = bit_and_carry;
    }
    let mut absorption = *z;
    absorption[7] = QM31::ONE.sub(absorption[7]);
    absorption[6] = QM31::ONE.sub(absorption[6]);
    [*z, successor, absorption]
}
